        runCase(
            "indoor_support_sampling_prefers_highest_floor_under_body_footprint",
            [&](std::string &failure)
            {
                if (!gameDataLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "d18.blv"))
                {
                    failure = "could not load d18.blv";
                    return false;
                }

                const std::optional<MapAssetInfo> &loadedMap = gameDataLoader.getSelectedMap();

                if (!loadedMap || !loadedMap->indoorMapData || !loadedMap->indoorMapDeltaData || !loadedMap->eventRuntimeState)
                {
                    failure = "d18.blv missing indoor state";
                    return false;
                }

                std::optional<EventRuntimeState> runtimeState = *loadedMap->eventRuntimeState;
                RuntimeMechanismState mechanism = {};
                mechanism.state = static_cast<uint16_t>(EvtMechanismState::Open);
                mechanism.currentDistance = 0.0f;
                mechanism.isMoving = false;
                runtimeState->mechanisms[1] = mechanism;

                IndoorMovementController controller(
                    *loadedMap->indoorMapData,
                    &loadedMap->indoorMapDeltaData,
                    &runtimeState);

                for (size_t sectorIndex : {size_t(1), size_t(3), size_t(8)})
                {
                    if (sectorIndex >= loadedMap->indoorMapData->sectors.size())
                    {
                        failure = "expected d18 sector is missing from parsed indoor data";
                        return false;
                    }

                    const IndoorSector &sector = loadedMap->indoorMapData->sectors[sectorIndex];

                    if (sector.floorFaceIds.empty() || sector.faceIds.empty())
                    {
                        failure = "parsed d18 sector lists are incomplete for sector " + std::to_string(sectorIndex);
                        return false;
                    }
                }

                const IndoorBodyDimensions body = {};
                IndoorMoveState current =
                    controller.initializeStateFromEyePosition(480.0f, 930.0f, 16.0f, body);
                float minimumFootZ = current.footZ;
                float maximumFootZ = current.footZ;

                // In the party's fixed movement step: with 0.1 s steps gravity sinks the body into the door's 36-wide
                // floor slot between steps, which the game never does.
                for (int step = 0; step < 307; ++step)
                {
                    current = controller.resolveMove(current, body, 0.0f, 40.0f, false, 1.0f / 128.0f);
                    minimumFootZ = std::min(minimumFootZ, current.footZ);
                    maximumFootZ = std::max(maximumFootZ, current.footZ);

                    if (current.footZ < -200.0f)
                    {
                        failure = "movement snapped into the retracted door pocket while approaching the doorway";
                        return false;
                    }
                }

                if (current.y < 980.0f)
                {
                    failure = "movement failed to continue through the open doorway "
                        + describeIndoorFaceMembership(*loadedMap->indoorMapData, 383);
                    return false;
                }

                if (maximumFootZ - minimumFootZ > 24.0f)
                {
                    failure = "movement oscillated vertically while crossing the open doorway pocket";
                    return false;
                }

                return true;
            }
        );

        runCase(
            "indoor_support_sampling_prefers_raised_open_door_surface_at_d18_seam",
            [&](std::string &failure)
            {
                if (!gameDataLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "d18.blv"))
                {
                    failure = "could not load d18.blv";
                    return false;
                }

                const std::optional<MapAssetInfo> &loadedMap = gameDataLoader.getSelectedMap();

                if (!loadedMap || !loadedMap->indoorMapData || !loadedMap->indoorMapDeltaData || !loadedMap->eventRuntimeState)
                {
                    failure = "d18.blv missing indoor state";
                    return false;
                }

                std::optional<EventRuntimeState> runtimeState = *loadedMap->eventRuntimeState;
                RuntimeMechanismState mechanism = {};
                mechanism.state = static_cast<uint16_t>(EvtMechanismState::Open);
                mechanism.currentDistance = 0.0f;
                mechanism.isMoving = false;
                runtimeState->mechanisms[1] = mechanism;

                IndoorMovementController controller(
                    *loadedMap->indoorMapData,
                    &loadedMap->indoorMapDeltaData,
                    &runtimeState);
                const IndoorBodyDimensions body = {};
                IndoorMoveState current =
                    controller.initializeStateFromEyePosition(-592.862f, -541.367f, 16.0f, body);
                bool reachedSeamSupport = false;

                // Running from room floor 13 (z -144) onto the doorway floor 1364 (z -128): touching the raised floor's
                // edge steps the body up early, and it must end on that floor once its centre is over it.
                constexpr size_t RaisedDoorwayFace = 1364;

                for (int step = 0; step < 24; ++step)
                {
                    current = controller.resolveMove(current, body, -37.2438f, 1279.46f, false, 0.00158256f);

                    if (current.supportFaceIndex == RaisedDoorwayFace)
                    {
                        reachedSeamSupport = true;
                    }
                }

                if (!reachedSeamSupport)
                {
                    failure = "movement did not step onto the raised doorway support at the seam "
                        + describeIndoorFaceMembership(*loadedMap->indoorMapData, RaisedDoorwayFace)
                        + " final=(" + std::to_string(current.x) + "," + std::to_string(current.y) + ","
                        + std::to_string(current.footZ) + ") supportFace="
                        + std::to_string(current.supportFaceIndex)
                        + " sector=" + std::to_string(current.sectorId);
                    return false;
                }

                if (current.supportFaceIndex != RaisedDoorwayFace || std::fabs(current.footZ - (-128.0f)) > 0.1f)
                {
                    failure = "movement did not remain on the doorway seam support after crossing the seam";
                    return false;
                }

                return true;
            }
        );

        runCase(
            "indoor_d17_dragon_cave_hostility_stays_friendly_after_reload_restore",
            [&](std::string &failure)
            {
                if (!gameDataLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "d17.blv"))
                {
                    failure = "could not load d17.blv";
                    return false;
                }

                const std::optional<MapAssetInfo> &loadedMap = gameDataLoader.getSelectedMap();

                if (!loadedMap || !loadedMap->indoorMapData)
                {
                    failure = "selected map missing indoor data";
                    return false;
                }

                IndoorRegressionScenario scenario = {};

                if (!initializeIndoorRegressionScenario(gameDataLoader, *loadedMap, scenario))
                {
                    failure = "could not initialize d17 indoor scenario";
                    return false;
                }

                scenario.party.setQuestBit(233, true); // You have Pissed of the Dragons
                scenario.party.setEventVariableValue(static_cast<uint16_t>(EvtVariable::Counter10), 1);
                scenario.eventRuntimeState->variables[static_cast<uint32_t>(EvtVariable::DayOfYear)] = 57;
                scenario.eventRuntimeState->variables[static_cast<uint32_t>(EvtVariable::Hour)] = 1;

                if (!scenario.eventRuntime.executeEventById(
                        loadedMap->localEventProgram,
                        loadedMap->globalEventProgram,
                        5,
                        *scenario.eventRuntimeState,
                        &scenario.party,
                        nullptr))
                {
                    failure = "could not execute d17 dragon on-load event";
                    return false;
                }

                scenario.world.applyEventRuntimeState(true);

                const uint32_t hostileMask = static_cast<uint32_t>(EvtActorAttribute::Hostile);

                for (uint32_t groupId : {uint32_t(44), uint32_t(45), uint32_t(11)})
                {
                    const auto clearIt = scenario.eventRuntimeState->actorGroupClearMasks.find(groupId);

                    if (clearIt == scenario.eventRuntimeState->actorGroupClearMasks.end()
                        || (clearIt->second & hostileMask) == 0)
                    {
                        failure = "d17 on-load state did not persist Hostile clear mask for group "
                            + std::to_string(groupId);
                        return false;
                    }
                }

                auto assertDragonGroupsFriendly =
                    [](const IndoorWorldRuntime &world,
                       const std::optional<MapDeltaData> &mapDeltaData,
                       const std::string &phase,
                       std::string &failure) -> bool
                    {
                        if (!mapDeltaData)
                        {
                            failure = phase + ": map delta missing";
                            return false;
                        }

                        size_t checkedActorCount = 0;

                        for (size_t actorIndex = 0; actorIndex < mapDeltaData->actors.size(); ++actorIndex)
                        {
                            const MapDeltaActor &actor = mapDeltaData->actors[actorIndex];

                            if (actor.group != 11 && actor.group != 44 && actor.group != 45)
                            {
                                continue;
                            }

                            GameplayRuntimeActorState actorState = {};

                            if (!world.actorRuntimeState(actorIndex, actorState))
                            {
                                failure = phase + ": actorRuntimeState failed";
                                return false;
                            }

                            if (actorState.hostileToParty || actorState.hasDetectedParty)
                            {
                                std::ostringstream stream;
                                stream << phase
                                       << ": actor=" << actorIndex
                                       << " group=" << actor.group
                                       << " hostile=" << actorState.hostileToParty
                                       << " detected=" << actorState.hasDetectedParty;
                                failure = stream.str();
                                return false;
                            }

                            ++checkedActorCount;
                        }

                        if (checkedActorCount == 0)
                        {
                            failure = phase + ": no dragon cave group actors checked";
                            return false;
                        }

                        return true;
                    };

                if (!assertDragonGroupsFriendly(scenario.world, scenario.mapDeltaData, "initial load", failure))
                {
                    return false;
                }

                IndoorWorldRuntime::Snapshot snapshot = scenario.world.snapshot();

                for (size_t actorIndex = 0;
                     actorIndex < snapshot.mapActorAiStates.size() && actorIndex < scenario.mapDeltaData->actors.size();
                     ++actorIndex)
                {
                    const MapDeltaActor &actor = scenario.mapDeltaData->actors[actorIndex];

                    if (actor.group != 11 && actor.group != 44 && actor.group != 45)
                    {
                        continue;
                    }

                    snapshot.mapActorAiStates[actorIndex].hostileToParty = true;
                    snapshot.mapActorAiStates[actorIndex].hasDetectedParty = true;
                    snapshot.mapActorAiStates[actorIndex].spellEffects.hostileToParty = true;
                    snapshot.mapActorAiStates[actorIndex].spellEffects.hasDetectedParty = true;
                }

                std::optional<MapDeltaData> restoredMapDelta = scenario.mapDeltaData;
                std::optional<EventRuntimeState> restoredEventRuntimeState = scenario.eventRuntimeState;

                if (!restoredEventRuntimeState)
                {
                    failure = "restored event runtime state missing";
                    return false;
                }

                clearTransientEventRuntimeState(*restoredEventRuntimeState);

                GameplayActorService actorService = buildBoundGameplayActorService(gameDataLoader);
                IndoorWorldRuntime restoredWorld = {};
                restoredWorld.initialize(
                    loadedMap->map,
                    gameDataLoader.getMonsterTable(),
                    gameDataLoader.getObjectTable(),
                    gameDataLoader.getItemTable(),
                    gameDataLoader.getChestTable(),
                    &scenario.party,
                    nullptr,
                    &restoredMapDelta,
                    &restoredEventRuntimeState,
                    &actorService,
                    nullptr,
                    &*loadedMap->indoorMapData);

                if (!assertDragonGroupsFriendly(
                        restoredWorld,
                        restoredMapDelta,
                        "reload without transient hostility requests",
                        failure))
                {
                    return false;
                }

                restoredWorld.restoreSnapshot(snapshot);

                if (!assertDragonGroupsFriendly(restoredWorld, restoredMapDelta, "snapshot restore", failure))
                {
                    return false;
                }

                std::optional<size_t> attackedActorIndex;

                for (size_t actorIndex = 0; actorIndex < restoredMapDelta->actors.size(); ++actorIndex)
                {
                    const MapDeltaActor &actor = restoredMapDelta->actors[actorIndex];

                    if (actor.group == 44 && actor.hp > 1)
                    {
                        attackedActorIndex = actorIndex;
                        break;
                    }
                }

                if (!attackedActorIndex.has_value())
                {
                    failure = "could not find a group 44 dragon to attack";
                    return false;
                }

                if (!restoredWorld.applyPartyAttackMeleeDamage(
                        *attackedActorIndex,
                        1,
                        GameplayWorldPoint{0.0f, 0.0f, 0.0f}, ShieldAttackTier::Physical))
                {
                    failure = "party attack did not apply to d17 dragon";
                    return false;
                }

                GameplayRuntimeActorState attackedState = {};

                if (!restoredWorld.actorRuntimeState(*attackedActorIndex, attackedState)
                    || !attackedState.hostileToParty
                    || !attackedState.hasDetectedParty)
                {
                    failure = "attacked d17 dragon did not become hostile";
                    return false;
                }

                if (!scenario.eventRuntime.executeEventById(
                        loadedMap->localEventProgram,
                        loadedMap->globalEventProgram,
                        452,
                        *restoredEventRuntimeState,
                        &scenario.party,
                        &restoredWorld))
                {
                    failure = "could not execute d17 initial room pressure plate event";
                    return false;
                }

                restoredWorld.applyEventRuntimeState();

                if (!restoredWorld.actorRuntimeState(*attackedActorIndex, attackedState)
                    || !attackedState.hostileToParty
                    || !attackedState.hasDetectedParty)
                {
                    failure = "initial room pressure plate cleared attack hostility";
                    return false;
                }

                return true;
            }
        );

        runCase(
            "indoor_actor_audio_follows_damage_hooks_and_state_transitions",
            [&](std::string &failure)
            {
                if (!gameDataLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "d18.blv"))
                {
                    failure = "could not load d18.blv";
                    return false;
                }
                IndoorRegressionScenario scenario = {};
                if (!initializeIndoorRegressionScenario(gameDataLoader, *gameDataLoader.getSelectedMap(), scenario))
                {
                    failure = "indoor audio scenario initialization failed";
                    return false;
                }
                size_t index = 0;
                const MonsterTable::MonsterStatsEntry *pStats = nullptr;
                for (; index < scenario.world.mapActorCount(); ++index)
                {
                    GameplayRuntimeActorState actor = {};
                    scenario.world.actorRuntimeState(index, actor);
                    pStats = gameDataLoader.getMonsterTable().findStatsById(actor.monsterId);
                    if (!actor.isDead && !actor.isInvisible && pStats != nullptr
                        && pStats->winceSoundId != 0 && pStats->deathSoundId != 0 && pStats->boredSoundId != 0)
                    {
                        break;
                    }
                }
                if (index == scenario.world.mapActorCount())
                {
                    failure = "no voiced indoor actor";
                    return false;
                }
                const auto resetActor = [&](ActorAiMotionState motion)
                {
                    scenario.mapDeltaData->actors[index].hp = 100;
                    IndoorWorldRuntime::Snapshot snapshot = scenario.world.snapshot();
                    snapshot.mapActorAiStates[index].motionState = motion;
                    snapshot.mapActorAiStates[index].animationState = motion == ActorAiMotionState::Attacking
                        ? ActorAiAnimationState::AttackMelee : ActorAiAnimationState::Standing;
                    snapshot.mapActorAiStates[index].actionSeconds = 1;
                    scenario.world.restoreSnapshot(snapshot);
                    scenario.eventRuntimeState->pendingSounds.clear();
                };
                const auto voiceCount = [&](uint32_t soundId)
                {
                    return std::count_if(scenario.eventRuntimeState->pendingSounds.begin(),
                        scenario.eventRuntimeState->pendingSounds.end(),
                        [&](const EventRuntimeState::PendingSound &sound)
                        {
                            return sound.actorIndex == index && sound.soundId == soundId;
                        });
                };
                resetActor(ActorAiMotionState::Standing);
                IndoorWorldRuntime::Snapshot idleSnapshot = scenario.world.snapshot();
                IndoorWorldRuntime::MapActorAiState &idle = idleSnapshot.mapActorAiStates[index];
                for (idle.idleDecisionCount = 0; idle.idleDecisionCount < 10000; ++idle.idleDecisionCount)
                {
                    if (actorChoosesBored(idle.actorId, idle.idleDecisionCount)
                        && actorBoredSoundRoll(idle.actorId, idle.idleDecisionCount))
                    {
                        break;
                    }
                }
                idle.actionSeconds = 0.001f;
                idle.idleDecisionSeconds = 0.001f;
                scenario.world.restoreSnapshot(idleSnapshot);
                scenario.world.updateTurnBasedPausedActorAnimations(0.01f);
                scenario.world.updateTurnBasedPausedActorAnimations(0.01f);
                if (voiceCount(pStats->boredSoundId) != 1)
                {
                    failure = "indoor turn-based fidget did not emit one voice on entry";
                    return false;
                }
                resetActor(ActorAiMotionState::Standing);
                scenario.world.applyPartyAttackMeleeDamage(index, 1, {}, ShieldAttackTier::Physical);
                scenario.world.applyPartyAttackMeleeDamage(index, 1, {}, ShieldAttackTier::Physical);
                if (voiceCount(pStats->winceSoundId) != 1 || voiceCount(pStats->deathSoundId) != 0)
                {
                    failure = "indoor repeated hit did not share reaction eligibility";
                    return false;
                }
                resetActor(ActorAiMotionState::Attacking);
                scenario.world.applyPartyAttackMeleeDamage(index, 1, {}, ShieldAttackTier::Physical);
                if (voiceCount(pStats->winceSoundId) != 0)
                {
                    failure = "attacking indoor actor cried on ordinary damage";
                    return false;
                }

                std::optional<ScriptedEventProgram> hook;
                const std::optional<ScriptedEventProgram> noGlobal;
                for (int damageOverride : {0, 1})
                {
                    resetActor(ActorAiMotionState::Standing);
                    hook = ScriptedEventProgram::loadFromLuaText(
                        "evt.meta.map.monsterDamageHooks = {65000}\n"
                        "evt.map[65000] = function() evt.SetHookDamage("
                            + std::to_string(damageOverride) + ") end",
                        "actor_audio_test.lua", ScriptedEventScope::Map, failure);
                    if (!hook)
                    {
                        return false;
                    }
                    scenario.world.bindEventExecution(&scenario.eventRuntime, &hook, &noGlobal);
                    scenario.world.applyPartyAttackMeleeDamage(index, 10000, {}, ShieldAttackTier::Physical);
                    if (scenario.mapDeltaData->actors[index].hp != 100 - damageOverride
                        || voiceCount(pStats->deathSoundId) != 0
                        || voiceCount(pStats->winceSoundId) != damageOverride)
                    {
                        failure = "indoor audio predicted damage before the event hook";
                        return false;
                    }
                }
                hook.reset();
                resetActor(ActorAiMotionState::Standing);
                scenario.world.applyPartyAttackMeleeDamage(index, 10000, {}, ShieldAttackTier::Physical);
                scenario.world.applyPartyAttackMeleeDamage(index, 10000, {}, ShieldAttackTier::Physical);
                scenario.world.updateTurnBasedPausedActorAnimations(0.01f);
                if (voiceCount(pStats->deathSoundId) != 1 || voiceCount(pStats->winceSoundId) != 0)
                {
                    failure = "indoor lethal transition did not emit exactly one death voice";
                    return false;
                }
                return true;
            });

        runCase(
            "indoor_world_runtime_exposes_actor_queries_and_direct_damage",
            [&](std::string &failure)
            {
                if (!gameDataLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "d18.blv"))
                {
                    failure = "could not load d18.blv";
                    return false;
                }

                const std::optional<MapAssetInfo> &loadedMap = gameDataLoader.getSelectedMap();

                if (!loadedMap || !loadedMap->indoorMapData || !loadedMap->indoorMapDeltaData || !loadedMap->eventRuntimeState)
                {
                    failure = "d18.blv missing indoor authored/runtime state";
                    return false;
                }

                std::optional<MapDeltaData> indoorMapDeltaData = *loadedMap->indoorMapDeltaData;
                std::optional<EventRuntimeState> eventRuntimeState = *loadedMap->eventRuntimeState;
                Party party = {};
                party.setItemTable(&gameDataLoader.getItemTable());
                party.setCharacterDollTable(&gameDataLoader.getCharacterDollTable());
                party.setItemEnchantTables(
                    &gameDataLoader.getStandardItemEnchantTable(),
                    &gameDataLoader.getSpecialItemEnchantTable());
                party.setClassMultiplierTable(&gameDataLoader.getClassMultiplierTable());
                party.setClassSkillTable(&gameDataLoader.getClassSkillTable());
                party.seed(createRegressionPartySeed());

                GameplayActorService actorService = buildBoundGameplayActorService(gameDataLoader);
                IndoorWorldRuntime worldRuntime = {};
                worldRuntime.initialize(
                    loadedMap->map,
                    gameDataLoader.getMonsterTable(),
                    gameDataLoader.getObjectTable(),
                    gameDataLoader.getItemTable(),
                    gameDataLoader.getChestTable(),
                    &party,
                    nullptr,
                    &indoorMapDeltaData,
                    &eventRuntimeState,
                    &actorService,
                    nullptr,
                    &*loadedMap->indoorMapData);

                if (worldRuntime.mapActorCount() != indoorMapDeltaData->actors.size())
                {
                    failure = "indoor actor count does not match delta actor count";
                    return false;
                }

                std::optional<size_t> selectedActorIndex;

                for (size_t actorIndex = 0; actorIndex < worldRuntime.mapActorCount(); ++actorIndex)
                {
                    const MapDeltaActor &actor = indoorMapDeltaData->actors[actorIndex];

                    if (actor.hp > 20
                        && (actor.attributes & static_cast<uint32_t>(EvtActorAttribute::Invisible)) == 0)
                    {
                        selectedActorIndex = actorIndex;
                        break;
                    }
                }

                if (!selectedActorIndex.has_value())
                {
                    failure = "could not find a living visible indoor actor";
                    return false;
                }

                const size_t actorIndex = *selectedActorIndex;
                const MapDeltaActor &initialActor = indoorMapDeltaData->actors[actorIndex];
                GameplayRuntimeActorState actorState = {};

                if (!worldRuntime.actorRuntimeState(actorIndex, actorState))
                {
                    failure = "actorRuntimeState failed for a valid indoor actor";
                    return false;
                }

                if (std::abs(actorState.preciseX - static_cast<float>(initialActor.x)) > 0.01f
                    || std::abs(actorState.preciseY - static_cast<float>(initialActor.y)) > 0.01f
                    || std::abs(actorState.preciseZ - static_cast<float>(initialActor.z)) > 0.01f
                    || actorState.height == 0
                    || actorState.radius == 0)
                {
                    failure = "indoor actor query did not expose initialized actor runtime geometry";
                    return false;
                }

                const float actorCenterZ =
                    actorState.preciseZ + std::max(24.0f, static_cast<float>(actorState.height) * 0.7f);
                const std::vector<size_t> nearbyActors = worldRuntime.collectMapActorIndicesWithinRadius(
                    actorState.preciseX,
                    actorState.preciseY,
                    actorCenterZ,
                    1.0f,
                    false,
                    actorState.preciseX,
                    actorState.preciseY,
                    actorCenterZ);

                if (std::find(nearbyActors.begin(), nearbyActors.end(), actorIndex) == nearbyActors.end())
                {
                    failure = "radius query did not return the actor at the query center";
                    return false;
                }

                const int initialHp = indoorMapDeltaData->actors[actorIndex].hp;

                if (!worldRuntime.applyPartySpellToActor(
                        actorIndex,
                        spellIdValue(SpellId::Blades),
                        10,
                        SkillMastery::Master,
                        17,
                        0.0f,
                        0.0f,
                        0.0f,
                        0,
                        false))
                {
                    failure = "direct indoor actor damage failed";
                    return false;
                }

                if (indoorMapDeltaData->actors[actorIndex].hp >= initialHp)
                {
                    failure = "direct indoor actor damage did not update hp";
                    return false;
                }

                return true;
            }
        );

