    runCase(
        "outdoor_ground_actor_walking_preserves_falling_velocity",
        [&](std::string &failure)
        {
            RegressionScenario scenario = {};
            if (!initializeRegressionScenario(gameDataLoader, *selectedMap, scenario))
            {
                failure = "scenario init failed";
                return false;
            }

            OutdoorWorldRuntime::Snapshot snapshot = scenario.world.snapshot();
            size_t actorIndex = snapshot.mapActors.size();
            for (size_t index = 0; index < snapshot.mapActors.size(); ++index)
            {
                const OutdoorWorldRuntime::MapActorState &actor = snapshot.mapActors[index];
                const MonsterTable::MonsterStatsEntry *pStats =
                    gameDataLoader.getMonsterTable().findStatsById(actor.monsterId);
                if (pStats != nullptr && !pStats->canFly && actor.moveSpeed > 0
                    && !actor.isDead && !actor.hostileToParty
                    && pStats->movementType != MonsterTable::MonsterMovementType::Stationary)
                {
                    actorIndex = index;
                    break;
                }
            }
            if (actorIndex == snapshot.mapActors.size())
            {
                failure = "no walking ground actor available";
                return false;
            }

            OutdoorWorldRuntime::MapActorState &actor = snapshot.mapActors[actorIndex];
            actor.preciseZ += 4000.0f;
            actor.z = static_cast<int>(std::lround(actor.preciseZ));
            actor.homePreciseZ = actor.preciseZ;
            actor.homeZ = actor.z;
            actor.aiState = OutdoorWorldRuntime::ActorAiState::Wandering;
            actor.animation = OutdoorWorldRuntime::ActorAnimation::Walking;
            actor.actionSeconds = 10.0f;
            actor.idleDecisionSeconds = 10.0f;
            actor.moveDirectionX = 1.0f;
            actor.moveDirectionY = 0.0f;
            actor.velocityZ = 0.0f;
            actor.movementStateInitialized = false;
            snapshot.actorUpdateAccumulatorSeconds = 0.0f;
            const float startX = actor.preciseX;
            const float startY = actor.preciseY;
            const float startZ = actor.preciseZ;
            scenario.world.restoreSnapshot(snapshot);

            size_t walkingTicks = 0;
            for (int tick = 0; tick < 64; ++tick)
            {
                scenario.world.updateMapActors(1.0f / 128.0f, startX + 1000.0f, startY, startZ);
                const OutdoorWorldRuntime::MapActorState *pActor = scenario.world.mapActorState(actorIndex);
                if (pActor != nullptr && pActor->animation == OutdoorWorldRuntime::ActorAnimation::Walking)
                {
                    ++walkingTicks;
                }
            }
            const OutdoorWorldRuntime::MapActorState *pActor = scenario.world.mapActorState(actorIndex);
            if (pActor == nullptr || walkingTicks < 60 || std::abs(pActor->preciseX - startX) < 1.0f)
            {
                failure = "actor did not exercise walking integration while airborne: walking_ticks="
                    + std::to_string(walkingTicks) + " delta_x="
                    + std::to_string(pActor != nullptr ? pActor->preciseX - startX : 0.0f);
                return false;
            }
            if (!pActor->movementState.airborne || pActor->preciseZ > startZ - 150.0f
                || pActor->preciseZ < startZ - 180.0f || pActor->velocityZ > -630.0f)
            {
                failure = "walking actor did not accumulate gravity: drop="
                    + std::to_string(startZ - pActor->preciseZ) + " velocity=" + std::to_string(pActor->velocityZ);
                return false;
            }
            return true;
        }
    );

    runCase(
        "jeric_whistlebone_actor_stays_on_terrain_floor_under_tent",
        [&](std::string &failure)
        {
            GameDataLoader garroteLoader;

            if (!garroteLoader.loadForHeadlessGameplay(assetFileSystem)
                || !garroteLoader.loadMapByFileNameForHeadlessGameplay(assetFileSystem, "out05.odm"))
            {
                failure = "could not load out05.odm";
                return false;
            }

            const std::optional<MapAssetInfo> &garroteMap = garroteLoader.getSelectedMap();

            if (!garroteMap || !garroteMap->outdoorMapData || !garroteMap->outdoorMapDeltaData)
            {
                failure = "out05 map missing outdoor data";
                return false;
            }

            constexpr size_t JericActorIndex = 3;

            if (garroteMap->outdoorMapDeltaData->actors.size() <= JericActorIndex)
            {
                failure = "Jeric actor missing from out05";
                return false;
            }

            const MapDeltaActor &rawActor = garroteMap->outdoorMapDeltaData->actors[JericActorIndex];
            const float worldX = static_cast<float>(rawActor.x);
            const float worldY = static_cast<float>(rawActor.y);
            const float rawZ = static_cast<float>(rawActor.z);
            const float terrainHeight = sampleOutdoorRenderedTerrainHeight(*garroteMap->outdoorMapData, worldX, worldY);
            const float legacyPlacementHeight = sampleOutdoorPlacementFloorHeight(
                *garroteMap->outdoorMapData,
                worldX,
                worldY,
                rawZ);
            const float actorPlacementHeight = sampleOutdoorActorPlacementFloorHeight(
                *garroteMap->outdoorMapData,
                worldX,
                worldY,
                rawZ,
                static_cast<float>(rawActor.radius));

            if (legacyPlacementHeight <= terrainHeight + 32.0f)
            {
                failure = "Jeric test actor is not under a raised tent support";
                return false;
            }

            if (std::fabs(actorPlacementHeight - terrainHeight) > 2.0f)
            {
                failure = "Jeric actor placement did not resolve to terrain";
                return false;
            }

            RegressionScenario scenario = {};

            if (!initializeRegressionScenario(garroteLoader, *garroteMap, scenario))
            {
                failure = "scenario init failed";
                return false;
            }

            const OutdoorWorldRuntime::MapActorState *pActor = scenario.world.mapActorState(JericActorIndex);

            if (pActor == nullptr)
            {
                failure = "Jeric actor missing from runtime";
                return false;
            }

            if (pActor->movementState.supportKind != OutdoorSupportKind::Terrain)
            {
                failure = "Jeric movement state did not use terrain support";
                return false;
            }

            if (std::fabs(pActor->preciseZ - terrainHeight) > 2.0f)
            {
                failure = "Jeric runtime z does not match terrain floor";
                return false;
            }

            return true;
        }
    );

    runCase(
        "friendly_actor_3_stands_and_faces_party_on_contact",
        [&](std::string &failure)
        {
            MapAssetInfo modifiedMap = *selectedMap;
            modifiedMap.outdoorMapDeltaData = *selectedMap->outdoorMapDeltaData;
            modifiedMap.outdoorMapDeltaData->locationInfo.lastRespawnDay = 1;
            RegressionScenario scenario = {};

            if (!initializeRegressionScenario(gameDataLoader, modifiedMap, scenario))
            {
                failure = "scenario init failed";
                return false;
            }

            const OutdoorWorldRuntime::MapActorState *pBefore = scenario.world.mapActorState(3);

            if (pBefore == nullptr)
            {
                failure = "actor 3 missing";
                return false;
            }

            const float partyX = static_cast<float>(pBefore->x + 32);
            const float partyY = static_cast<float>(pBefore->y + 24);
            const float partyZ = static_cast<float>(pBefore->z);
            scenario.world.updateMapActors(0.25f, static_cast<float>(pBefore->x + 20000), static_cast<float>(pBefore->y + 20000), partyZ);
            scenario.world.notifyPartyContactWithMapActor(3, partyX, partyY, partyZ);
            const OutdoorWorldRuntime::MapActorState *pAfter = scenario.world.mapActorState(3);

            if (pAfter == nullptr)
            {
                failure = "actor 3 missing after update";
                return false;
            }

            if (pAfter->aiState != OutdoorWorldRuntime::ActorAiState::Standing)
            {
                failure = "actor 3 did not stand on party contact";
                return false;
            }

            if (pAfter->animation != OutdoorWorldRuntime::ActorAnimation::Standing)
            {
                failure = "actor 3 did not use standing animation on party contact";
                return false;
            }

            if (std::abs(pAfter->velocityX) > 0.01f || std::abs(pAfter->velocityY) > 0.01f)
            {
                failure = "actor 3 kept moving on party contact";
                return false;
            }

            const float expectedYaw = std::atan2(partyY - pAfter->preciseY, partyX - pAfter->preciseX);

            if (angleDistanceRadians(pAfter->yawRadians, expectedYaw) > 0.35f)
            {
                failure = "actor 3 did not face the party on contact";
                return false;
            }

            return true;
        }
    );

