            request.ability = OutdoorWorldRuntime::MonsterAttackAbility::Spell1;
            request.spellId = spellIdValue(SpellId::LightningBolt);
            request.skillLevel = 10;
            request.skillMastery = static_cast<uint32_t>(SkillMastery::Expert);
