    runCase(
        "app_transport_transition_preserves_hired_npc_followers",
        [&](std::string &failure)
        {
            const std::string previousWorldId = assetFileSystem.getActiveWorldId();
            if (!assetFileSystem.switchActiveWorld("mm6"))
            {
                failure = "could not activate MM6 assets";
                return false;
            }

            struct ActiveWorldRestore
            {
                Engine::AssetFileSystem &assetFileSystem;
                std::string worldId;

                ~ActiveWorldRestore()
                {
                    assetFileSystem.switchActiveWorld(worldId);
                }
            } activeWorldRestore = {assetFileSystem, previousWorldId};

            SDL_Environment *pEnvironment = SDL_GetEnvironment();
            if (pEnvironment == nullptr
                || !SDL_SetEnvironmentVariable(pEnvironment, "SDL_AUDIODRIVER", "dummy", true))
            {
                failure = "could not force dummy audio driver for MM6 travel regression";
                return false;
            }

            if (!GameApplicationTestAccess::loadGameData(mm6HirelingTravelSession.application, assetFileSystem))
            {
                failure = "could not load MM6 gameplay data";
                return false;
            }

            mm6HirelingTravelSession.isGameDataLoaded = true;
            GameApplicationTestAccess::setBootSeededDwiOnNextRendererInit(
                mm6HirelingTravelSession.application,
                true);
            if (!GameApplicationTestAccess::initializeStartupSession(mm6HirelingTravelSession.application, false))
            {
                failure = "could not initialize New Sorpigal startup runtime";
                return false;
            }

            GameApplication &application = mm6HirelingTravelSession.application;
            GameDataLoader &loader = GameApplicationTestAccess::gameDataLoader(application);
            OutdoorWorldRuntime *pWorld = GameApplicationTestAccess::outdoorWorldRuntime(application);
            OutdoorPartyRuntime *pPartyRuntime = GameApplicationTestAccess::outdoorPartyRuntime(application);
            const HouseEntry *pStable = loader.getHouseTable().get(470);

            if (pWorld == nullptr || pPartyRuntime == nullptr || pStable == nullptr)
            {
                failure = "New Sorpigal stable travel state is incomplete";
                return false;
            }

            Party &party = pPartyRuntime->party();
            EventRuntimeState *pEventRuntimeState = pWorld->eventRuntimeState();

            if (pEventRuntimeState == nullptr)
            {
                failure = "New Sorpigal event runtime state is missing";
                return false;
            }

            constexpr uint32_t FollowerNpcId = 1184;
            HiredNpcFollower follower = {FollowerNpcId, 20, 300};
            follower.name = "Generated Merchant";
            follower.pictureId = 123;
            party.addHiredNpcFollower(follower);
            party.applyGlobalNpcStateTo(*pEventRuntimeState);
            party.addGold(10000);

            const std::vector<HouseActionOption> actions = buildHouseActionOptions(
                *pStable,
                &party,
                &loader.getClassSkillTable(),
                pWorld,
                pWorld->gameMinutes(),
                DialogueMenuId::None);
            const std::vector<HouseActionOption>::const_iterator routeIt = std::find_if(
                actions.begin(),
                actions.end(),
                [](const HouseActionOption &option)
                {
                    return option.id == HouseActionId::TransportRoute
                        && option.label.find("Castle Ironfist") != std::string::npos;
                });

            if (routeIt == actions.end())
            {
                failure = "New Sorpigal stable has no Castle Ironfist route today";
                return false;
            }

            const HouseActionResult result = performHouseAction(
                *routeIt,
                *pStable,
                party,
                &loader.getClassSkillTable(),
                pWorld,
                &loader.getNpcDialogTable());

            if (!result.succeeded || !pEventRuntimeState->pendingMapMove)
            {
                failure = "New Sorpigal stable route did not request travel";
                return false;
            }

            if (!GameApplicationTestAccess::processPendingMapMove(application))
            {
                failure = "New Sorpigal to Castle Ironfist transition failed";
                return false;
            }

            const IMapSceneRuntime *pArrivingScene = GameApplicationTestAccess::mapSceneRuntime(application);
            if (pArrivingScene == nullptr
                || toLowerCopy(std::filesystem::path(pArrivingScene->currentMapFileName()).filename().string())
                    != "outd3.odm")
            {
                failure = "stable travel did not arrive at Castle Ironfist";
                return false;
            }

            const Party::Snapshot arrivingParty = pArrivingScene->party().snapshot();
            const bool followerStillHired = std::find_if(
                arrivingParty.hiredNpcFollowers.begin(),
                arrivingParty.hiredNpcFollowers.end(),
                [](const HiredNpcFollower &entry)
                {
                    return entry.npcId == FollowerNpcId;
                }) != arrivingParty.hiredNpcFollowers.end();

            if (!followerStillHired)
            {
                failure = "hired NPC follower disappeared during stable travel";
                return false;
            }

            const EventRuntimeState *pArrivingRuntimeState = pArrivingScene->eventRuntimeState();
            if (pArrivingRuntimeState == nullptr
                || pArrivingRuntimeState->npcNameOverrides.find(FollowerNpcId)
                    == pArrivingRuntimeState->npcNameOverrides.end()
                || pArrivingRuntimeState->npcNameOverrides.at(FollowerNpcId) != follower.name
                || pArrivingRuntimeState->npcPictureOverrides.find(FollowerNpcId)
                    == pArrivingRuntimeState->npcPictureOverrides.end()
                || pArrivingRuntimeState->npcPictureOverrides.at(FollowerNpcId) != follower.pictureId)
            {
                failure = "generated hired NPC identity disappeared during stable travel";
                return false;
            }

            return true;
        }
    );

    runCase(
        "app_rest_overlay_blocks_flying_and_hostile_range",
        [&](std::string &failure)
        {
            if (!prepareSharedHeadlessGameApplication(
                    out02ViewSession,
                    assetFileSystem,
                    "out02.odm",
                    true,
                    failure))
            {
                return false;
            }

            GameApplication &application = out02ViewSession.application;

            OutdoorWorldRuntime *pWorld = GameApplicationTestAccess::outdoorWorldRuntime(application);
            OutdoorPartyRuntime *pPartyRuntime = GameApplicationTestAccess::outdoorPartyRuntime(application);

            if (pWorld == nullptr || pPartyRuntime == nullptr)
            {
                failure = "application state is incomplete";
                return false;
            }

            Party &party = pPartyRuntime->party();
            Character *pActiveMember = party.activeMember();
            const OutdoorMoveState initialMoveState = pPartyRuntime->movementState();

            if (pActiveMember == nullptr)
            {
                failure = "missing active member";
                return false;
            }

            party.clearPartyBuff(PartyBuffId::Fly);
            GameApplicationTestAccess::openRestOverlay(application);

            if (!GameApplicationTestAccess::isRestScreenActive(application))
            {
                failure = "rest overlay did not open in a clear outdoor location";
                return false;
            }

            GameApplicationTestAccess::closeRestOverlay(application);
            pActiveMember->portraitState = PortraitId::Normal;
            pActiveMember->portraitElapsedTicks = 0;
            pActiveMember->portraitDurationTicks = 0;
            party.applyPartyBuff(PartyBuffId::Fly, 600.0f, 1, 0, 0, SkillMastery::None, 0);
            pPartyRuntime->syncSpellMovementStatesFromPartyBuffs();
            pPartyRuntime->toggleFlying();
            GameApplicationTestAccess::openRestOverlay(application);

            if (GameApplicationTestAccess::isRestScreenActive(application)
                || GameApplicationTestAccess::statusBarEventText(application) != "You can't rest here!")
            {
                failure = "rest overlay did not block while flying";
                return false;
            }

            if (pActiveMember->portraitState == PortraitId::Normal)
            {
                failure = "failed rest did not trigger the can't-rest face reaction";
                return false;
            }

            party.clearPartyBuff(PartyBuffId::Fly);
            pPartyRuntime->syncSpellMovementStatesFromPartyBuffs();

            std::optional<GameplayRuntimeActorState> hostileActor;

            for (size_t actorIndex = 0; actorIndex < pWorld->mapActorCount(); ++actorIndex)
            {
                GameplayRuntimeActorState actorState = {};

                if (pWorld->actorRuntimeState(actorIndex, actorState)
                    && !actorState.isDead
                    && !actorState.isInvisible
                    && actorState.hostileToParty)
                {
                    hostileActor = actorState;
                    break;
                }
            }

            if (!hostileActor.has_value())
            {
                failure = "test map has no hostile actor for rest range coverage";
                return false;
            }

            pPartyRuntime->teleportTo(
                hostileActor->preciseX + 128.0f,
                hostileActor->preciseY,
                hostileActor->preciseZ);
            GameApplicationTestAccess::openRestOverlay(application);

            if (GameApplicationTestAccess::isRestScreenActive(application)
                || GameApplicationTestAccess::statusBarEventText(application) != "There are hostile enemies near!")
            {
                failure = "rest overlay did not block near a hostile actor";
                return false;
            }

            pPartyRuntime->teleportTo(initialMoveState.x, initialMoveState.y, initialMoveState.footZ);
            return true;
        }
    );

    runCase(
        "app_tavern_rent_room_closes_dialog_runs_rest_ui_and_wakes_at_6am",
        [&](std::string &failure)
        {
            if (!prepareSharedHeadlessGameApplication(
                    out02ViewSession,
                    assetFileSystem,
                    "out02.odm",
                    true,
                    failure))
            {
                return false;
            }

            GameApplication &application = out02ViewSession.application;

            OutdoorWorldRuntime *pWorld = GameApplicationTestAccess::outdoorWorldRuntime(application);
            OutdoorPartyRuntime *pPartyRuntime = GameApplicationTestAccess::outdoorPartyRuntime(application);
            EventRuntimeState *pEventRuntimeState = pWorld != nullptr ? pWorld->eventRuntimeState() : nullptr;
            const HouseEntry *pTavernHouse =
                GameApplicationTestAccess::gameDataLoader(application).getHouseTable().get(229);

            if (pWorld == nullptr || pPartyRuntime == nullptr || pEventRuntimeState == nullptr || pTavernHouse == nullptr)
            {
                failure = "application state is incomplete";
                return false;
            }

            Party &party = pPartyRuntime->party();
            Character *pActiveMember = party.activeMember();

            if (pActiveMember == nullptr)
            {
                failure = "missing active member";
                return false;
            }

            party.addGold(1000);
            party.applyPartyBuff(PartyBuffId::WizardEye, 600.0f, 1, 0, 0, SkillMastery::None, 0);
            pActiveMember->health = std::max(1, pActiveMember->health - 17);
            pActiveMember->spellPoints = std::max(0, pActiveMember->spellPoints - 4);
            pActiveMember->conditions.set(static_cast<size_t>(CharacterCondition::Asleep));
            pActiveMember->recoverySecondsRemaining = 2.0f;

            const float targetGameMinutes = nextGameMinuteAtOrAfter(pWorld->gameMinutes(), 16.0f * 60.0f + 30.0f);
            pWorld->advanceGameMinutes(targetGameMinutes - pWorld->gameMinutes());
            const float initialGameMinutes = pWorld->gameMinutes();
            const float expectedRestMinutes = 13.0f * 60.0f + 30.0f;

            EventRuntimeState::PendingDialogueContext context = {};
            context.kind = DialogueContextKind::HouseService;
            context.sourceId = pTavernHouse->id;
            context.hostHouseId = pTavernHouse->id;
            pEventRuntimeState->dialogueState.hostHouseId = pTavernHouse->id;
            pEventRuntimeState->pendingDialogueContext = std::move(context);

            GameApplicationTestAccess::openPendingEventDialog(application, pEventRuntimeState->messages.size(), true);

            if (!GameApplicationTestAccess::hasActiveEventDialog(application))
            {
                failure = "tavern did not open an active dialog";
                return false;
            }

            // The house lists its residents first: the innkeep's services are behind the first one.
            GameApplicationTestAccess::setEventDialogSelectionIndex(application, 0);
            GameApplicationTestAccess::executeActiveDialogAction(application);

            const EventDialogContent &dialog = GameApplicationTestAccess::activeEventDialog(application);
            const std::string expectedRoomActionLabel =
                "Rent room for " + std::to_string(PriceCalculator::tavernRoomPrice(pActiveMember, *pTavernHouse)) + " gold";

            if (dialog.actions.empty() || dialog.actions.front().label != expectedRoomActionLabel)
            {
                failure = "tavern dialog did not expose rent room as the first action";
                return false;
            }

            GameApplicationTestAccess::setEventDialogSelectionIndex(application, 0);
            GameApplicationTestAccess::executeActiveDialogAction(application);

            if (GameApplicationTestAccess::hasActiveEventDialog(application))
            {
                failure = "rent room did not close the active dialog";
                return false;
            }

            if (!GameApplicationTestAccess::isRestScreenActive(application))
            {
                failure = "rent room did not open the rest screen";
                return false;
            }

            if (std::abs(GameApplicationTestAccess::restRemainingMinutes(application) - expectedRestMinutes) > 0.01f)
            {
                failure = "rest screen did not use the OE tavern rest duration";
                return false;
            }

            if (std::abs(pWorld->gameMinutes() - initialGameMinutes) > 0.01f)
            {
                failure = "rent room advanced time immediately instead of waiting in the rest screen";
                return false;
            }

            if (pActiveMember->recoverySecondsRemaining != 2.0f
                || !pActiveMember->conditions.test(static_cast<size_t>(CharacterCondition::Asleep))
                || !party.hasPartyBuff(PartyBuffId::WizardEye))
            {
                failure = "rent room applied recovery before the rest screen completed";
                return false;
            }

            GameApplicationTestAccess::updateRestScreen(application, 5.0f);

            if (GameApplicationTestAccess::isRestScreenActive(application))
            {
                failure = "rest screen did not close after the inn rest completed";
                return false;
            }

            if (std::abs(pWorld->gameMinutes() - (initialGameMinutes + expectedRestMinutes)) > 0.01f)
            {
                failure = "inn rest advanced an unexpected amount of time";
                return false;
            }

            const float wakeMinuteOfDay = std::fmod(std::max(0.0f, pWorld->gameMinutes()), 1440.0f);

            if (std::abs(wakeMinuteOfDay - 360.0f) > 0.01f)
            {
                failure = "inn rest did not finish at 6:00 AM";
                return false;
            }

            if (pActiveMember->health != pActiveMember->maxHealth + pActiveMember->magicalBonuses.maxHealth
                || pActiveMember->spellPoints != pActiveMember->maxSpellPoints + pActiveMember->magicalBonuses.maxSpellPoints
                || pActiveMember->recoverySecondsRemaining != 0.0f
                || pActiveMember->conditions.test(static_cast<size_t>(CharacterCondition::Asleep))
                || party.hasPartyBuff(PartyBuffId::WizardEye))
            {
                failure = "inn rest did not apply full rest recovery on completion";
                return false;
            }

            return true;
        }
    );

